'use strict';
// Authorized business-export import. No source application code or credentials.
const FIRST_DRIVE_BACKUP='https://drive.google.com/file/d/1R7vhFvYx_BpRnaCjCiNC83TkBBKgd9i-/view?usp=drivesdk';
const listKeyMap={accessories:'Vehicle Accessories',customer_types:'Customer Types',expense_categories:'Expense Categories',fuel_levels:'Fuel Levels',fuel_types:'Fuel Types',job_statuses:'Job Card Statuses',mechanic_specializations:'Mechanic Specializations',part_categories:'Spare Part Categories',part_units:'Part Units (UOM)',payment_modes:'Payment Modes',service_types:'Imported Service Types',staff_designations:'Staff Designations',transmission_types:'Transmission Types',vehicle_brands:'Vehicle Brands',vehicle_types:'Vehicle Types',work_types:'Work Types'};
function normalizeImported(source){let result=structuredClone(source);result.users=structuredClone(seed.users);result.lists={...structuredClone(seed.lists),...Object.fromEntries(Object.entries(source.lists||{}).map(([k,v])=>[listKeyMap[k]||k,v]))};return result}
const importedBusiness=window.BIKE_DOCTOR_IMPORT?normalizeImported(window.BIKE_DOCTOR_IMPORT):null;
if(importedBusiness&&!db.importInfo&&!db.audit.length){try{if(localStorage.getItem(STORE))localStorage.setItem(STORE+'-before-demo-import',JSON.stringify(db));db=structuredClone(importedBusiness);save()}catch{toast('Import could not be saved. Download a backup to keep your work.')}}
const originalBillTotals=billTotals;
billTotals=function(b){return b.importedTotals?{...b.importedTotals}:originalBillTotals(b)};
const originalPaid=paid;
paid=function(b){return b.imported?round(Number(b.importedPaid||0)+db.receipts.filter(r=>r.bill===b.id&&!r.historical).reduce((s,r)=>s+Number(r.amount),0)):originalPaid(b)};
allReceipts=function(){return [...db.jobs,...db.sales].filter(b=>Number(b.advance)>0&&b.status!=='Cancelled').map(b=>({id:b.id+'-ADV',date:b.date,bill:b.id,amount:b.advance,account:b.account,mode:b.mode||'Cash',party:b.customer?name('customers',b.customer):b.walkin||'Walk-in Customer'})).concat(db.receipts.map(r=>({...r,party:r.party||(find('jobs',r.bill)?.customer?name('customers',find('jobs',r.bill).customer):'Walk-in Customer')})))};
const originalNextId=nextId;
nextId=function(key){let prefix=key==='jobs'?db.settings.jobPrefix:key==='customers'?db.settings.customerPrefix:key==='bikes'?db.settings.vehiclePrefix:prefixes[key];let n=Math.max(1000,...db[key].map(x=>Number(String(x.id).split('~')[0].match(/(\d+)$/)?.[1])||1000))+1,id=`${prefix||prefixes[key]}-${n}`;while(db[key].some(x=>x.id===id))id=`${prefix||prefixes[key]}-${++n}`;return id};
const originalBillForm=billForm;
billForm=function(key,id,initial){let b=id&&find(key,id);if(b?.imported){invoice(key,id);toast('Imported historical bill: original amounts preserved. Create a new job for new work.');return}return originalBillForm(key,id,initial)};
function logoMarkup(cls=''){let logo=db.settings.logo;return logo&&/^data:image\/(png|jpeg|webp);base64,/.test(logo)?`<img class="garageLogo ${cls}" src="${esc(logo)}" alt="Imported demo garage logo">`:`<div class="brandmark ${cls}"><span>BD</span><small>MOTO CARE</small></div>`}
function appLogoMarkup(){return '<img class="garageLogo appBrandLogo" src="bike-doctor-icon-192.png" alt="The Bike Doctor logo">'}
function backupObject(){let data=structuredClone(db);data.users=data.users.map(u=>({id:u.id,name:u.name,username:u.username,role:u.role,status:u.status}));return {format:'BIKE_DOCTOR_BACKUP',version:1,createdAt:new Date().toISOString(),data}}
function downloadBackup(){download(JSON.stringify(backupObject(),null,2),`BIKE-DOCTOR-backup-${today()}-${Date.now()}.json`,'application/json');localStorage.setItem(STORE+'-last-download',new Date().toISOString());toast('Backup downloaded. Upload this JSON file to Google Drive.');}
function validateBackup(text){let o=typeof text==='string'?JSON.parse(text):text;let data=o.format==='BIKE_DOCTOR_BACKUP'?o.data:o;let keys=['customers','bikes','parts','services','staff','accounts','jobs','sales','purchases','receipts','expenses','appointments','insurance','users','audit'];if(!data||typeof data!=='object'||!data.settings||!data.lists)throw Error('This is not a BIKE DOCTOR backup.');for(let key of keys){if(!Array.isArray(data[key]))throw Error('Missing or invalid '+key);if(data[key].length>100000)throw Error('Backup has too many records.');let ids=new Set();for(let row of data[key]){if(!row||typeof row.id!=='string'||ids.has(row.id))throw Error('Invalid or duplicate ID in '+key);ids.add(row.id)}}let clean=JSON.parse(JSON.stringify(data),(k,v)=>['__proto__','constructor','prototype','password','token','access_token','refresh_token','clientSecret','aadhaar'].includes(k)?undefined:v);clean.users=clean.users.map(u=>({id:u.id,name:u.name,username:u.username,role:u.role,status:u.status}));clean.attendance=clean.attendance||{};clean.lists={...structuredClone(seed.lists),...Object.fromEntries(Object.entries(clean.lists).map(([k,v])=>[listKeyMap[k]||k,v]))};if(!clean.users.length)clean.users=structuredClone(seed.users);return clean}
function confirmRestore(data){openModal('Review Backup Before Restoring',`<div class="formbody"><div class="notice">Restoring replaces the current browser records. A safety copy of the current workspace will be downloaded first.</div>${summary([['CUSTOMERS',data.customers.length],['VEHICLES',data.bikes.length],['JOB CARDS',data.jobs.length],['PARTS',data.parts.length]])}<p>Garage: <strong>${esc(data.settings.name)}</strong></p></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn danger" id="confirmRestore">Download Safety Copy & Restore</button></div>`);$('#confirmRestore').onclick=()=>{downloadBackup();db=data;audit('Restore','Business backup restored in this browser');if(save('Backup restored')){closeModal();render()}}}
function backupPanel(){return `<section class="panel" style="margin-top:20px"><div class="panelhead"><h2>${icon('shield')}Database Backup & Google Drive</h2><span class="badge good">First backup saved to Drive</span></div><div class="panelbody"><p style="color:#64748b;line-height:1.7">Keep a JSON backup of customers, vehicles, jobs, inventory and payments. The first imported business-data backup was saved to your connected Google Drive on 23 October 2026.</p><div class="toolbar">${btn('Download Database (JSON)','downloadBusiness','secondary','download')}<button class="btn secondary" id="restoreFileButton">${icon('file')}Restore Backup</button><a class="btn success" href="${FIRST_DRIVE_BACKUP}" target="_blank" rel="noopener">View First Drive Backup ↗</a><a class="btn secondary" href="https://drive.google.com/drive/my-drive" target="_blank" rel="noopener">Open Google Drive ↗</a></div><input type="file" id="restoreFile" accept=".json,application/json" hidden><div class="notice"><strong>Works now:</strong> Download a JSON backup → open Google Drive → New → File upload → choose the downloaded backup. To restore, download the JSON from Drive and use Restore Backup here.</div><details><summary style="cursor:pointer;font-weight:600;padding:10px 0">Direct Google Drive backup setup</summary><p style="color:#64748b;line-height:1.7">Direct backup uses your Google account chooser and the limited drive.file permission. It needs a hosted HTTPS address (or localhost) and an OAuth web client registered for that address. It cannot connect from this downloaded file. Do not enter a client secret or password.</p><form id="driveConfigForm"><label class="field"><span>GOOGLE OAUTH WEB CLIENT ID (PUBLIC CONFIGURATION)</span><input name="clientId" placeholder="…apps.googleusercontent.com" value="${esc(localStorage.getItem(STORE+'-drive-client')||'')}"></label><div class="toolbar" style="margin-top:12px"><button class="btn secondary" type="submit">Save Client ID</button><button class="btn success" type="button" id="driveBackupButton">Back Up Now to Google Drive</button></div></form><div id="driveStatus" class="notice">${location.protocol==='file:'?'Direct connection unavailable in a file preview. Use the download/upload method above.':'Not connected. Google authorization will be requested only when you click Back Up Now.'}</div><p style="color:#64748b;font-size:11px">Backup runs only after your click, while the application is open. No background or automatic cloud sync is enabled.</p></details></div></section>`}
const originalSettingsPage=settingsPage;
settingsPage=function(){let html=originalSettingsPage().replace('Sample tax is 0%. Production billing treatment must be confirmed before real invoices are issued.','Historical demo invoice totals are preserved. Confirm production billing treatment before issuing real invoices.').replace('<div class="brandmark" style="background:#0b1120;margin:20px auto"><span>BD</span><small>MOTO CARE</small></div>',`<div class="brandingPreview">${logoMarkup()}</div>`).replace('Original BIKE DOCTOR identity','Imported demo logo · replace it with your own logo when ready').replace('Download Sample Backup','Download Database Backup').replace('No external messages, bank transfers or customer data imports are connected.','Demo business records have been imported; credentials and cloud administrator settings are excluded.');return html+`<section class="panel"><div class="panelhead"><h2>${icon('box')}Imported Demo Business Records</h2><span class="badge info">${db.importInfo?'Loaded':'Available'}</span></div><div class="panelbody"><p>${importedBusiness?.customers.length||0} customers · ${importedBusiness?.bikes.length||0} vehicles · ${importedBusiness?.parts.length||0} parts · ${importedBusiness?.services.length||0} services · ${importedBusiness?.jobs.length||0} jobs · ${importedBusiness?.receipts.length||0} payment records</p><p style="color:#64748b;font-size:11px;line-height:1.7">Source data is preserved as a historical import. Duplicate source IDs use a ~2 suffix internally. Users/passwords, hosting settings, banking numbers, payment QR/signature and staff identity numbers are excluded.</p><div class="toolbar"><button class="btn secondary" id="demoInvoiceButton">${icon('print')}View Imported Invoice Sample</button><button class="btn secondary" id="loadDemoButton">Reload Original Demo Records…</button></div><label class="field"><span>GARAGE LOGO (PNG / JPEG / WEBP, MAX 1 MB)</span><input type="file" id="logoFile" accept="image/png,image/jpeg,image/webp"></label></div></section>`+backupPanel()};
invoice=function(key,id){let b=find(key,id);if(!b)return;let t=billTotals(b),c=find('customers',b.customer);let services=(b.serviceLines||[]).map(l=>({name:(l.name||name('services',l.service))+(typeof itemDiscountDescription==='function'?itemDiscountDescription(l,'service'):''),discountText:typeof invoiceItemDiscountText==='function'?invoiceItemDiscountText(l,'service'):'—',qty:1,rate:Number(l.charge||0),tax:typeof serviceGstRate==='function'?serviceGstRate(l,b):Number(b.tax||0),amount:typeof serviceLineAmount==='function'?serviceLineAmount(l,b):(typeof itemNet==='function'?itemNet(l,'service'):Number(l.charge||0))})),parts=(b.partLines||[]).map(l=>({name:(l.name||name('parts',l.part))+(typeof itemDiscountDescription==='function'?itemDiscountDescription(l,'part'):''),discountText:typeof invoiceItemDiscountText==='function'?invoiceItemDiscountText(l,'part'):'—',qty:l.qty,rate:l.price,tax:Number(l.gst||0),amount:typeof itemNet==='function'&&hasItemDiscount(b)?itemNet(l,'part')*(1+Number(b.invoiceType==='non-gst'?0:l.gst||0)/100):b.imported&&l.sourceAmount?l.sourceAmount:l.qty*l.price*(1+Number(b.invoiceType==='non-gst'?0:l.gst||0)/100)}));openModal('Invoice / Account Statement',`<div class="invoice invoiceV2"><div class="taxCaption">${b.imported?'IMPORTED INVOICE COPY':'PROTOTYPE INVOICE'}</div><div class="invoicebrand"><div class="invoiceIdentity">${logoMarkup()}<div><h2>${esc(db.settings.name)}</h2><strong>GARAGE MANAGEMENT SYSTEM</strong><p>${esc(db.settings.address||'')}<br>Phone: ${esc(db.settings.phone||'—')}<br>GSTIN: ${esc(db.settings.gst||'—')} · State: ${esc(db.settings.state||'—')}</p></div></div><div style="text-align:right"><h3>${esc(b.sourceId||id)}</h3><p>Invoice Date: ${esc(b.date)}<br>Job Status: ${esc(b.status||'Completed')}</p></div></div><div class="invoiceinfo"><div><small>CUSTOMER DETAILS</small><br><strong>${esc(c?.name||b.customerName||b.walkin||'Walk-in Customer')}</strong><br>${esc(c?.mobile||'')}<br>${esc(c?.address||'')}<br>${esc(c?.gst?'GSTIN: '+c.gst:'')}</div><div><small>VEHICLE & JOB DETAILS</small><br><strong>${esc(b.vehicleNumber||number(b.bike))}</strong><br>${esc(find('bikes',b.bike)?.brand||'')} ${esc(find('bikes',b.bike)?.model||'')}<br>${esc(b.work||'Counter Sale')}<br>Odometer: ${esc(b.odometer||'—')} km</div></div>${b.complaint?`<div class="invoiceComplaint"><strong>Customer complaint:</strong> ${esc(b.complaint)}</div>`:''}${services.length?`<h4>LABOUR / SERVICE CHARGES</h4>${table(['Service / Description','Qty','Rate','Item Discount','GST (%)','Amount'],services.map(l=>[esc(l.name),l.qty,money(l.rate),esc(l.discountText||'—'),l.tax+'%',money(l.amount)]))}`:''}${parts.length?`<h4>SPARE PARTS</h4>${table(['Part / Description','Qty','Rate','Item Discount','GST (%)','Amount'],parts.map(l=>[esc(l.name),l.qty,money(l.rate),esc(l.discountText||'—'),l.tax+'%',money(l.amount)]))}`:''}<div class="invoiceBottom"><div><p><strong>Payment Status</strong><br>${payStatus(b)}</p><p>Assigned mechanic: ${esc(b.mechanicName||name('staff',b.mechanic))}</p><p>${esc(b.notes||'')}</p><p class="invoiceCaution">${b.imported?'Source totals are preserved from the demo export. This copy is for reference; it does not reissue or certify the original invoice.':'Prototype document. Confirm tax treatment and invoice rules before business use.'}</p></div><div class="invoicetotal"><p><span>Labour</span><b>${money(t.labour)}</b></p><p><span>Parts</span><b>${money(t.parts)}</b></p><p><span>Total Discount</span><b>− ${money(invoiceDiscount(b))}</b></p><p><span>Tax / Source Adjustment</span><b>${money(t.tax)}</b></p><p class="grand"><span>Grand Total</span><span>${money(t.total)}</span></p><p><span>Paid / Advance</span><b>${money(paid(b))}</b></p><p><span>Due Amount</span><b>${money(due(b))}</b></p></div></div><div class="invoiceFoot"><p>${esc(db.settings.footer||'Thank you for your business.')}</p><div>For ${esc(db.settings.name)}<br><br><br>Authorized Signatory</div></div></div><div class="formactions">${btn('Close','cancel','secondary')}${btn('Print / Save PDF','print','','print')}</div>`)};
let driveToken=null,driveTokenExpires=0,driveBusy=false;
function loadGoogleIdentity(){if(window.google?.accounts?.oauth2)return Promise.resolve();return new Promise((resolve,reject)=>{let script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>window.google?.accounts?.oauth2?resolve():reject(Error('Google sign-in did not load.'));script.onerror=()=>reject(Error('Cannot load Google sign-in. Check your internet connection.'));document.head.appendChild(script)})}
async function backUpToDrive(){if(driveBusy)return;let status=$('#driveStatus');const show=t=>{if(status)status.textContent=t};if(location.protocol==='file:'){show('Open a hosted BIKE DOCTOR address to use direct sign-in. Download and upload the backup to Drive for now.');return}let clientId=localStorage.getItem(STORE+'-drive-client');if(!clientId||!clientId.endsWith('.apps.googleusercontent.com')){show('Save a valid public OAuth web client ID first. No client secret is needed.');return}driveBusy=true;try{await loadGoogleIdentity();if(!driveToken||Date.now()>=driveTokenExpires){show('Waiting for your Google account authorization…');let token=await new Promise((resolve,reject)=>{let client=google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/drive.file',callback:r=>r.error?reject(Error(r.error_description||r.error)):resolve(r),error_callback:r=>reject(Error(r.message||r.type||'Google sign-in was cancelled.'))});client.requestAccessToken({prompt:'consent'})});if(!google.accounts.oauth2.hasGrantedAllScopes(token,'https://www.googleapis.com/auth/drive.file'))throw Error('Google Drive permission was not granted.');driveToken=token.access_token;driveTokenExpires=Date.now()+Math.max(0,Number(token.expires_in)-60)*1000}show('Uploading a new backup to your Google Drive…');let form=new FormData(),filename=`BIKE-DOCTOR-backup-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;form.append('metadata',new Blob([JSON.stringify({name:filename,mimeType:'application/json',appProperties:{application:'BIKE_DOCTOR',backupVersion:'1'}})],{type:'application/json'}));form.append('file',new Blob([JSON.stringify(backupObject(),null,2)],{type:'application/json'}));let response=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,size,webViewLink',{method:'POST',headers:{Authorization:'Bearer '+driveToken},body:form});let file=await response.json();if(!response.ok||!file.id){if(response.status===401){driveToken=null;driveTokenExpires=0}throw Error(file.error?.message||'Google Drive did not confirm the upload.')}localStorage.setItem(STORE+'-last-drive',JSON.stringify({id:file.id,name:file.name,date:new Date().toISOString(),url:file.webViewLink||''}));show('Backup confirmed by Google Drive: '+file.name);audit('Backup','Business records backed up to Google Drive');save();toast('Google Drive backup saved')}catch(err){show('Backup not confirmed: '+err.message)}finally{driveBusy=false}}
const originalRender=render;
render=function(){originalRender();let brand=$('#sidebar .brandmark,#sidebar .brand > .garageLogo');if(brand&&!brand.classList.contains('appBrandLogo'))brand.outerHTML=appLogoMarkup();if(page==='settings'){let b=$('#demoInvoiceButton');if(b)b.onclick=()=>db.jobs[0]?invoice('jobs',db.jobs[0].id):toast('No job invoice available');if($('#loadDemoButton'))$('#loadDemoButton').onclick=()=>confirmRestore(structuredClone(importedBusiness));if($('#restoreFileButton'))$('#restoreFileButton').onclick=()=>$('#restoreFile').click();if($('#restoreFile'))$('#restoreFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;if(file.size>15*1024*1024)return toast('Backup exceeds 15 MB.');try{confirmRestore(validateBackup(await file.text()))}catch(err){toast('Restore rejected: '+err.message)}};if($('#logoFile'))$('#logoFile').onchange=e=>{let file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1024*1024)return toast('Choose PNG, JPEG or WebP up to 1 MB.');let reader=new FileReader();reader.onload=()=>{db.settings.logo=reader.result;audit('Update','Garage logo changed');save('Logo saved');render()};reader.readAsDataURL(file)};if($('#driveConfigForm'))$('#driveConfigForm').onsubmit=e=>{e.preventDefault();let value=new FormData(e.target).get('clientId').trim();if(value&&!/^[a-zA-Z0-9._-]+\.apps\.googleusercontent\.com$/.test(value))return toast('Enter the public OAuth web client ID, not a password or secret.');localStorage.setItem(STORE+'-drive-client',value);driveToken=null;toast('Public Google client ID saved')};if($('#driveBackupButton'))$('#driveBackupButton').onclick=backUpToDrive}}
document.addEventListener('click',e=>{let action=e.target.closest('[data-action]')?.dataset.action;if(action==='downloadBusiness')downloadBackup();if(action==='backup'){/* Base handler downloads the legacy JSON; restore accepts both formats. */}});
render();

